// Copy determinístico con variación controlada.
// Precio, nombre y enlaces salen de la BD: nunca los redacta un LLM.
const p = $input.first().json;

if (!p.slug || !p.image_url || !(Number(p.price) > 0)) {
  throw new Error(`Producto ${p.id} con datos incompletos (slug/imagen/precio)`);
}

const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
const cop = (n) => '$' + Math.round(Number(n)).toLocaleString('es-CO') + ' COP';

const ganchos = [
  '🎮 ¿Ya lo tienes en tu colección?',
  '🔥 Este no puede faltar en tu biblioteca.',
  '👾 Fin de semana resuelto.',
  '🕹️ Para los que juegan en serio.',
  '⚡ Llegó la hora de darle play.',
  '🏆 Un clásico que sigue dando guerra.',
  '🎯 ¿Buscabas tu próximo juego? Aquí está.',
];

const combos = [
  '🎁 Arma tu Combo: tu 2do y 3er juego llevan bono o regalo.',
  '🧩 ¿Uno solo? Arma tu Combo y el 2do y 3er juego vienen con bono o regalo.',
  '💥 Combo Mr Games: suma un 2do y 3er juego y te llevas bono o regalo.',
];

const ctas = [
  'Escríbenos por WhatsApp y te lo apartamos',
  'Pregunta disponibilidad por WhatsApp',
  'Haz tu pedido por WhatsApp',
];

// Claves adaptadas exactamente a los valores de products.platform en Supabase
const tagsPlataforma = {
  'Xbox': ['#Xbox', '#XboxColombia', '#XboxSeriesX', '#XboxOne'],
  'PlayStation 5': ['#PS5', '#PlayStation5', '#PlayStationColombia'],
  'Nintendo Switch': ['#NintendoSwitch', '#SwitchColombia', '#Nintendo'],
  'PC': ['#PCGaming', '#Steam', '#PCGamerColombia'],
};
const tagsGenerales = ['#Videojuegos', '#GamerColombia', '#JuegosColombia', '#Gaming'];

const plat = tagsPlataforma[p.platform] || ['#Xbox', '#XboxColombia'];
const hashtags = ['#MrGames', pick(plat), pick(tagsGenerales)]
  .filter((t, i, a) => a.indexOf(t) === i)
  .join(' ');

const waTexto = encodeURIComponent(`Hola Mr Games, me interesa ${p.name} (${p.platform}).`);
const waLink = `https://wa.me/573175942917?text=${waTexto}`;
const ficha = `https://mrgames.com.co/producto/${p.slug}`;

const caption = [
  pick(ganchos),
  '',
  `🎮 ${p.name}${p.platform ? ' · ' + p.platform : ''}`,
  `💰 ${cop(p.price)}`,
  '',
  pick(combos),
  '',
  `🛒 Ficha completa: ${ficha}`,
  `💬 ${pick(ctas)}: ${waLink}`,
  '',
  hashtags,
].join('\n');

if (caption.length > 2000) throw new Error('Caption demasiado largo');

return [{ json: { ...p, caption } }];

// Clasifica el error del Graph API para decidir la alerta.
const item = $input.first().json;
const crudo = JSON.stringify(item);
const prod = $('Armar copy').first().json;

const m = crudo.match(/\\?"code\\?"\s*:\s*(\d+)/);
const code = m ? Number(m[1]) : 0;
const msg = (item.error && (item.error.message || item.error.description)) || crudo.slice(0, 500);

let categoria = 'desconocido';
let severidad = 'media';
if ([190, 102, 10, 200].includes(code)) { categoria = 'token_o_permisos'; severidad = 'critica'; }
else if (code === 368) { categoria = 'bloqueo_por_politicas_spam'; severidad = 'critica'; }
else if ([4, 17, 32, 613].includes(code)) { categoria = 'rate_limit'; severidad = 'media'; }
else if ([324, 100].includes(code)) { categoria = 'imagen_o_parametros'; severidad = 'media'; }
else if (code === 0 && /ETIMEDOUT|ECONNRESET|ENOTFOUND|timeout|socket/i.test(crudo)) {
  categoria = 'red_o_timeout'; severidad = 'alta';
}

return [{ json: {
  product_id: prod.id,
  name: prod.name,
  slot: prod.slot,
  error_code: code,
  error_category: categoria,
  severidad,
  error_message: String(msg).slice(0, 1000),
} }];
